use vstd::prelude::*;

verus! {
    // Copy elements from dst or src into a new vector according to mask.
    // For each i, if mask[i] then result[i] == src[i] else result[i] == dst[i].
    fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> (result: Vec<T>)
        requires
            dst.len() == src.len(),
            src.len() == mask.len(),
        ensures
            result.len() == dst.len(),
            forall|i: usize| i < result.len() ==>
                if mask[i] { result[i] == src[i] } else { result[i] == dst[i] },
    {
        let n = dst.len();
        let mut i: usize = 0;
        let mut result = Vec::<T>::new();
        // Reserve space so pushes won't reallocate
        result.reserve(n);
        while i < n
            invariant
                i <= n,
                result.len() == i,
                // The partial result satisfies the selection rule up to i
                forall|j: usize| j < i ==>
                    if mask[j] { result[j] == src[j] } else { result[j] == dst[j] },
            decreases n - i,
        {
            // select from src or dst
            let x: T = if mask[i] { src[i] } else { dst[i] };
            result.push(x);
            i += 1;
        }
        result
    }
}

